-- seed.sql: datos SINTETICOS (Faker es_CO, semilla 2026) que simulan Banner-Cosmos.
-- Generado por db/seed/generar_datos.py. Ejecutar despues de las migraciones 001 a 006.
-- Borra y vuelve a cargar solo las tablas del simulador (no toca documentos, noticias ni n8n_chat_histories).
begin;
truncate table programas, periodos, estudiantes, cursos_ccd, profesores, calendario_academico, competencias_digitales restart identity cascade;
select setval(pg_get_serial_sequence('programas', 'id'), greatest((select coalesce(max(id), 1) from programas), 1));
select setval(pg_get_serial_sequence('cursos', 'id'), greatest((select coalesce(max(id), 1) from cursos), 1));
select setval(pg_get_serial_sequence('profesores', 'id'), greatest((select coalesce(max(id), 1) from profesores), 1));
select setval(pg_get_serial_sequence('matriculas', 'id'), greatest((select coalesce(max(id), 1) from matriculas), 1));
select setval(pg_get_serial_sequence('cursos_ccd', 'id'), greatest((select coalesce(max(id), 1) from cursos_ccd), 1));
select setval(pg_get_serial_sequence('historial_ccd', 'id'), greatest((select coalesce(max(id), 1) from historial_ccd), 1));
select setval(pg_get_serial_sequence('calendario_academico', 'id'), greatest((select coalesce(max(id), 1) from calendario_academico), 1));
select setval(pg_get_serial_sequence('competencias_digitales', 'id'), greatest((select coalesce(max(id), 1) from competencias_digitales), 1));
commit;
